private void xrTableCell25_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            string zbritje = string.IsNullOrEmpty(GetCurrentColumnValue("ZBRITJE").ToString()) ? "0" : GetCurrentColumnValue("ZBRITJE").ToString();
