private void xrTableCell43_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            string zbritje = string.IsNullOrEmpty(GetCurrentColumnValue("ZBRITJE").ToString()) ? "0" : GetCurrentColumnValue("ZBRITJE").ToString();
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(zbritje) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
